#!/usr/bin/env bash
# build-multi-game-ipa.sh — allocate several per-game AOT packages into ONE
# unsigned shell IPA, with a generated GameCatalog.json.
#
# Desktop AOT-first model (docs/desktop-aot.md):
#
#   out/packages/<TITLE_ID>/GameInfo.json + GamePack.dylib     (built on macOS)
#       -> one shell .app:
#            Frameworks/GamePack-<TITLE_ID>.dylib  (one per selected game)
#            GameCatalog.json                      (titleID -> packFile)
#       -> IPA/3ds2apple-multi-game-<version>.ipa (unsigned)
#
# The catalogue is generated by the Rust desktop CLI (3ds2apple-pack catalog), so
# the GameInfo/GameCatalog schemas have exactly one writer. App staging and
# zipping reuse scripts/package-ipa.sh.
#
# Modes:
#   --base-app APP   extend a real unsigned shell .app built by build-ios-app.sh
#                    (then the IPA is a real, installable-after-signing build)
#   --fake-shell     stage a minimal fake .app; works on Linux/Windows and is a
#                    LAYOUT PREVIEW only - it is not installable
#   --dry-run        validate inputs, generate the catalogue, print the plan
#
# Fake placeholder packs (from 3ds2apple-pack build --fake) are rejected unless
# --allow-placeholder-dylibs is passed, so a preview can never silently become a
# release.
#
# Compatibility: macOS system bash 3.2. Needs python3 (GameCatalog validation,
# as the existing build scripts do) and zip (via package-ipa.sh).
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

# shellcheck source=lib/game-catalog.sh
source "${SCRIPT_DIR}/lib/game-catalog.sh"
# shellcheck source=lib/desktop-aot.sh
source "${SCRIPT_DIR}/lib/desktop-aot.sh"

PACKAGES_DIR_ARG=""
ALL=0
TITLE_LIST=""
POSITIONAL_DIRS=""
CATALOG_ARG=""
CATALOG_OUT_ARG=""
BASE_APP_ARG=""
FAKE_SHELL=0
OUT_DIR_ARG="IPA"
IPA_NAME_ARG=""
IPA_VERSION_ARG=""
ALLOW_PLACEHOLDER=0
DRY_RUN=0
PACK_BIN_ARG=""

usage() {
  cat <<'EOF'
Allocate several per-game AOT packages into one unsigned shell IPA.

Usage:
  scripts/build-multi-game-ipa.sh [options] [PACKAGE_DIR...]

Package selection:
  PACKAGE_DIR...         Explicit package directories (each has GameInfo.json
                         + GamePack.dylib from scripts/build-game-pack.sh)
  --packages-dir DIR     Package root (default: out/packages) used with
                         --all / --title-id
  --all                  Select every package under --packages-dir
  --title-id ID          Select one title (repeatable)
  --catalog FILE         Use a pre-generated GameCatalog.json instead of
                         generating one (must list exactly the selected titles)
  --catalog-out FILE     Write the generated catalogue here
                         (default: <packages-root>/GameCatalog.json)

App / output:
  --base-app APP         Unsigned shell .app to extend (real mode)
  --fake-shell           Stage a minimal fake app (Linux preview; not installable)
  --out-dir DIR          IPA output directory (default: IPA/, gitignored)
  --ipa-name NAME        IPA base name without .ipa
                         (default: 3ds2apple-multi-game-<version>)
  --ipa-version VER      Version for the default name (default: the base app /
                         ios/app/project.yml version, else 0.0.0-dev)
  --dry-run              Validate, generate the catalogue, print the plan; no IPA

Safety / tooling:
  --allow-placeholder-dylibs  Accept --fake placeholder packs (preview only)
  --pack-bin PATH        Desktop CLI binary (default: builder/target/{release,debug}/,
                         PATH, or $THREEDS2APPLE_PACK)
  -h, --help             Show this help and exit

Outputs (gitignored by default):
  <out-dir>/<name>.ipa                  unsigned multi-game shell IPA
  <out-dir>/<name>.pack-manifest.txt    catalogue + per-pack SHA256 manifest
  <packages-root>/GameCatalog.json      generated catalogue (unless --catalog)

Signing stays with the user (Sideloadly / AltStore / SideStore); this script
only produces the unsigned IPA. The GamePack.dylib files and the IPA contain
game-derived code and must never be committed or redistributed.
EOF
}

log() { printf '[build-multi-game-ipa] %s\n' "$*"; }
warn() { printf '[build-multi-game-ipa] warning: %s\n' "$*" >&2; }
die() { printf 'error: %s\n' "$*" >&2; exit 1; }

resolve_path() {
  case "$1" in
    /*) printf '%s\n' "$1" ;;
    *) printf '%s\n' "${ROOT}/$1" ;;
  esac
}

append_line() { # file line
  printf '%s\n' "$2" >> "$1"
}

while [[ $# -gt 0 ]]; do
  case "$1" in
    --packages-dir) [[ $# -ge 2 ]] || die "--packages-dir requires a value"; PACKAGES_DIR_ARG="$2"; shift 2 ;;
    --all) ALL=1; shift ;;
    --title-id) [[ $# -ge 2 ]] || die "--title-id requires a value"; TITLE_LIST="${TITLE_LIST}${2}"$'\n'; shift 2 ;;
    --catalog) [[ $# -ge 2 ]] || die "--catalog requires a value"; CATALOG_ARG="$2"; shift 2 ;;
    --catalog-out) [[ $# -ge 2 ]] || die "--catalog-out requires a value"; CATALOG_OUT_ARG="$2"; shift 2 ;;
    --base-app) [[ $# -ge 2 ]] || die "--base-app requires a value"; BASE_APP_ARG="$2"; shift 2 ;;
    --fake-shell) FAKE_SHELL=1; shift ;;
    --out-dir) [[ $# -ge 2 ]] || die "--out-dir requires a value"; OUT_DIR_ARG="$2"; shift 2 ;;
    --ipa-name) [[ $# -ge 2 ]] || die "--ipa-name requires a value"; IPA_NAME_ARG="$2"; shift 2 ;;
    --ipa-version) [[ $# -ge 2 ]] || die "--ipa-version requires a value"; IPA_VERSION_ARG="$2"; shift 2 ;;
    --allow-placeholder-dylibs) ALLOW_PLACEHOLDER=1; shift ;;
    --pack-bin) [[ $# -ge 2 ]] || die "--pack-bin requires a value"; PACK_BIN_ARG="$2"; shift 2 ;;
    --dry-run) DRY_RUN=1; shift ;;
    -h|--help) usage; exit 0 ;;
    -*) die "unknown option: $1 (try --help)" ;;
    *) POSITIONAL_DIRS="${POSITIONAL_DIRS}${1}"$'\n'; shift ;;
  esac
done

if [[ -n "$BASE_APP_ARG" && "$FAKE_SHELL" -eq 1 ]]; then
  die "choose --base-app or --fake-shell, not both"
fi
if [[ -z "$POSITIONAL_DIRS" && "$ALL" -eq 0 && -z "$TITLE_LIST" ]]; then
  die "select packages: PACKAGE_DIR... or --all / --title-id (try --help)"
fi
if [[ -n "$POSITIONAL_DIRS" && "$ALL" -eq 1 ]]; then
  die "choose positional package directories or --all, not both"
fi

WORK="$(mktemp -d "${TMPDIR:-/tmp}/3ds2apple-multi-game.XXXXXX")"
SELECTED_FILE="${WORK}/selected-dirs.txt"
STAGE=""
cleanup() {
  if [[ -n "${STAGE:-}" && -d "${STAGE}" ]]; then rm -rf -- "${STAGE}"; fi
  rm -rf -- "${WORK}"
}
trap cleanup EXIT

# --- selection --------------------------------------------------------------
if [[ -n "$POSITIONAL_DIRS" ]]; then
  printf '%s' "$POSITIONAL_DIRS" > "${WORK}/raw-dirs.txt"
else
  if [[ -z "$PACKAGES_DIR_ARG" ]]; then
    PACKAGES_DIR="${ROOT}/out/packages"
  else
    PACKAGES_DIR="$(resolve_path "$PACKAGES_DIR_ARG")"
  fi
  [[ -d "$PACKAGES_DIR" ]] || die "packages dir not found: $PACKAGES_DIR"
  if [[ "$ALL" -eq 1 ]]; then
    find "$PACKAGES_DIR" -mindepth 1 -maxdepth 1 -type d | sort > "${WORK}/raw-dirs.txt"
  else
    : > "${WORK}/raw-dirs.txt"
    printf '%s' "$TITLE_LIST" | while IFS= read -r title; do
      [[ -n "$title" ]] || continue
      append_line "${WORK}/raw-dirs.txt" "${PACKAGES_DIR}/${title}"
    done
  fi
fi

: > "$SELECTED_FILE"
SEEN_FILE="${WORK}/seen.txt"
: > "$SEEN_FILE"
while IFS= read -r raw_dir; do
  [[ -n "$raw_dir" ]] || continue
  dir="$(resolve_path "$raw_dir")"
  [[ -d "$dir" ]] || die "package directory not found: $dir"
  [[ -f "${dir}/GameInfo.json" ]] || die "not a package directory (no GameInfo.json): $dir"
  title="$(basename "$dir")"
  case "$title" in
    *[!0-9A-F]*) die "package directory name is not a title ID: $dir" ;;
  esac
  [[ ${#title} -eq 16 ]] || die "package directory name is not a 16-digit title ID: $dir"
  case "$title" in
    00040000*) ;;
    *) die "package title ID is not an application title: $title" ;;
  esac
  if grep -qx "$title" "$SEEN_FILE" 2>/dev/null; then
    die "duplicate package for title $title in the selection"
  fi
  append_line "$SEEN_FILE" "$title"
  append_line "$SELECTED_FILE" "$dir"
done < "${WORK}/raw-dirs.txt"

[[ -s "$SELECTED_FILE" ]] || die "no packages selected"
# Sort by title ID (the file holds absolute paths; sort by the last segment),
# so catalogue/package processing order is deterministic.
awk -F/ '{print $NF "\t" $0}' "$SELECTED_FILE" | sort | cut -f2- > "${WORK}/selected-sorted.txt"
mv "${WORK}/selected-sorted.txt" "$SELECTED_FILE"
PACKAGE_COUNT="$(wc -l < "$SELECTED_FILE" | tr -d '[:space:]')"
[[ "$PACKAGE_COUNT" -gt 0 ]] || die "no packages selected"

# --- validate packs ---------------------------------------------------------
printf '[1/4] validating %s package(s)\n' "$PACKAGE_COUNT"
while IFS= read -r dir; do
  title="$(basename "$dir")"
  pack="${dir}/GamePack.dylib"
  if [[ ! -f "$pack" ]]; then
    die "missing pack file: $pack (run scripts/build-game-pack.sh for this title)"
  fi
  if desktop_aot_pack_is_placeholder "$pack"; then
    if [[ "$ALLOW_PLACEHOLDER" -eq 0 ]]; then
      die "package $title has a --fake placeholder pack; build the real pack on macOS or pass --allow-placeholder-dylibs for a layout preview"
    fi
    warn "package $title uses a --fake placeholder pack: the IPA is a layout preview only"
  elif ! desktop_aot_pack_is_macho "$pack"; then
    die "package $title: $pack is not a Mach-O dylib (nor a --fake placeholder)"
  fi
  printf '  %s  %s bytes  %s\n' "$title" "$(desktop_aot_file_bytes "$pack")" "$(desktop_aot_sha256 "$pack")"
done < "$SELECTED_FILE"

# --- catalogue --------------------------------------------------------------
printf '[2/4] preparing GameCatalog.json\n'
if [[ -n "$CATALOG_ARG" ]]; then
  CATALOG="$(resolve_path "$CATALOG_ARG")"
  [[ -f "$CATALOG" ]] || die "catalog not found: $CATALOG"
else
  if [[ -n "$CATALOG_OUT_ARG" ]]; then
    CATALOG="$(resolve_path "$CATALOG_OUT_ARG")"
  elif [[ -n "$PACKAGES_DIR_ARG" ]]; then
    CATALOG="$(resolve_path "$PACKAGES_DIR_ARG")/GameCatalog.json"
  elif [[ -n "$POSITIONAL_DIRS" ]]; then
    CATALOG="$(dirname "$(sed -n '1p' "$SELECTED_FILE")")/GameCatalog.json"
  else
    CATALOG="${ROOT}/out/packages/GameCatalog.json"
  fi
  mkdir -p "$(dirname "$CATALOG")"
  PACK_BIN="$(desktop_aot_find_pack_bin "$ROOT" "$PACK_BIN_ARG")" \
    || die "3ds2apple-pack binary not found ($(desktop_aot_pack_bin_hint))"
  CATALOG_ARGS=(catalog --catalog-out "$CATALOG")
  while IFS= read -r dir; do
    CATALOG_ARGS+=(--package-dir "$dir")
  done < "$SELECTED_FILE"
  "$PACK_BIN" "${CATALOG_ARGS[@]}"
fi

if ! game_catalog_validate "$CATALOG"; then
  die "invalid GameCatalog.json: ${GAME_CATALOG_ERROR}"
fi
CATALOG_SHA="$(desktop_aot_sha256 "$CATALOG")"
CATALOG_TITLES="$(desktop_aot_catalog_title_ids "$CATALOG" | sort)"
SELECTED_TITLES="$(while IFS= read -r dir; do basename "$dir"; done < "$SELECTED_FILE" | sort)"
if [[ "$CATALOG_TITLES" != "$SELECTED_TITLES" ]]; then
  die "GameCatalog.json games do not match the selected packages"
fi
log "catalog: $CATALOG ($(game_catalog_summary_text), sha256 $CATALOG_SHA)"

# --- version / name ---------------------------------------------------------
VERSION=""
if [[ -n "$IPA_VERSION_ARG" ]]; then
  VERSION="$IPA_VERSION_ARG"
elif [[ -n "$BASE_APP_ARG" ]] && [[ -x /usr/libexec/PlistBuddy ]]; then
  BASE_APP_RESOLVED="$(resolve_path "$BASE_APP_ARG")"
  if [[ -f "${BASE_APP_RESOLVED}/Info.plist" ]]; then
    VERSION="$(/usr/libexec/PlistBuddy -c 'Print :CFBundleShortVersionString' "${BASE_APP_RESOLVED}/Info.plist" 2>/dev/null || true)"
  fi
fi
if [[ -z "$VERSION" ]]; then
  VERSION="$(desktop_aot_project_version "$ROOT" || true)"
fi
if [[ -z "$VERSION" ]]; then VERSION="0.0.0-dev"; fi
desktop_aot_valid_version "$VERSION" || die "invalid version: '$VERSION' (letters, digits, '.', '_', '-')"

if [[ -n "$IPA_NAME_ARG" ]]; then
  IPA_NAME="${IPA_NAME_ARG%.ipa}"
else
  IPA_NAME="3ds2apple-multi-game-${VERSION}"
fi
[[ -n "$IPA_NAME" ]] || die "--ipa-name must not be empty"
case "$IPA_NAME" in
  */*) die "--ipa-name must be a file name, not a path: $IPA_NAME" ;;
  .*) die "--ipa-name must not start with a dot: $IPA_NAME" ;;
esac

OUT_DIR="$(resolve_path "$OUT_DIR_ARG")"
mkdir -p "$OUT_DIR"
OUT_DIR="$(cd "$OUT_DIR" && pwd)"
IPA_PATH="${OUT_DIR}/${IPA_NAME}.ipa"

MODE="real"
if [[ "$FAKE_SHELL" -eq 1 ]]; then MODE="fake-shell"; fi

if [[ "$DRY_RUN" -eq 1 ]]; then
  printf '[3/4] dry run: no IPA written\n'
  printf 'mode=%s\n' "$MODE"
  printf 'packages=%s\n' "$PACKAGE_COUNT"
  printf 'catalog=%s\n' "$CATALOG"
  printf 'catalog_sha256=%s\n' "$CATALOG_SHA"
  printf 'ipa=%s\n' "$IPA_PATH"
  printf 'ipa_name=%s\n' "$IPA_NAME"
  printf 'version=%s\n' "$VERSION"
  printf 'games:\n'
  while IFS= read -r dir; do
    printf '  %s  %s\n' "$(basename "$dir")" "$dir"
  done < "$SELECTED_FILE"
  exit 0
fi

# --- stage the shell app ----------------------------------------------------
printf '[3/4] staging the shell app (%s mode)\n' "$MODE"
STAGE="$(mktemp -d "${TMPDIR:-/tmp}/3ds2apple-multi-stage.XXXXXX")"
mkdir -p "${STAGE}/Payload"
if [[ -n "$BASE_APP_ARG" ]]; then
  BASE_APP="$(resolve_path "$BASE_APP_ARG")"
  [[ -d "$BASE_APP" ]] || die "base app not found: $BASE_APP"
  case "$BASE_APP" in
    *.app) ;;
    *) die "base app is not an .app bundle: $BASE_APP" ;;
  esac
  [[ -f "${BASE_APP}/Info.plist" ]] || die "base app has no Info.plist: $BASE_APP"
  APP_BASENAME="$(basename "$BASE_APP")"
  cp -R "$BASE_APP" "${STAGE}/Payload/"
  APP_STAGE="${STAGE}/Payload/${APP_BASENAME}"
  [[ -d "$APP_STAGE" ]] || die "failed to stage the base app"
else
  APP_BASENAME="3ds2apple.app"
  APP_STAGE="${STAGE}/Payload/${APP_BASENAME}"
  mkdir -p "$APP_STAGE"
  {
    printf '<?xml version="1.0" encoding="UTF-8"?>\n'
    printf '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n'
    printf '<plist version="1.0">\n<dict>\n'
    printf '  <key>CFBundleDevelopmentRegion</key><string>en</string>\n'
    printf '  <key>CFBundleExecutable</key><string>3ds2apple</string>\n'
    printf '  <key>CFBundleIdentifier</key><string>com.kratos.3ds2apple.multigame.preview</string>\n'
    printf '  <key>CFBundleInfoDictionaryVersion</key><string>6.0</string>\n'
    printf '  <key>CFBundleName</key><string>3ds2apple</string>\n'
    printf '  <key>CFBundleDisplayName</key><string>3ds2apple (preview)</string>\n'
    printf '  <key>CFBundlePackageType</key><string>APPL</string>\n'
    printf '  <key>CFBundleShortVersionString</key><string>%s</string>\n' "$VERSION"
    printf '  <key>CFBundleVersion</key><string>1</string>\n'
    printf '  <key>MinimumOSVersion</key><string>16.0</string>\n'
    printf '</dict>\n</plist>\n'
  } > "${APP_STAGE}/Info.plist"
  {
    printf '#!/bin/sh\n'
    printf '# Fake shell executable staged by scripts/build-multi-game-ipa.sh --fake-shell.\n'
    printf '# It is a layout preview only: this app is not installable.\n'
    printf 'echo "3ds2apple multi-game layout preview (not installable)"\n'
  } > "${APP_STAGE}/3ds2apple"
  chmod +x "${APP_STAGE}/3ds2apple"
fi

mkdir -p "${APP_STAGE}/Frameworks"
rm -f "${APP_STAGE}"/Frameworks/GamePack-*.dylib 2>/dev/null || true
rm -f "${APP_STAGE}/GameCatalog.json" "${APP_STAGE}/Resources/GameCatalog.json" 2>/dev/null || true
while IFS= read -r dir; do
  title="$(basename "$dir")"
  cp "${dir}/GamePack.dylib" "${APP_STAGE}/Frameworks/GamePack-${title}.dylib"
  printf '  embedded Frameworks/GamePack-%s.dylib\n' "$title"
  # Optional user-supplied cover; the catalogue entry carries coverFile when
  # the package has one (Covers are never committed to the repository).
  if [[ -f "${dir}/cover.png" ]]; then
    mkdir -p "${APP_STAGE}/Covers"
    cp "${dir}/cover.png" "${APP_STAGE}/Covers/${title}.png"
    printf '  embedded Covers/%s.png\n' "$title"
  fi
done < "$SELECTED_FILE"
cp "$CATALOG" "${APP_STAGE}/GameCatalog.json"
log "catalog installed in the app bundle: ${APP_STAGE}/GameCatalog.json"

# --- package ----------------------------------------------------------------
printf '[4/4] packaging IPA\n'
[[ -x "${ROOT}/scripts/package-ipa.sh" ]] || die "missing executable: ${ROOT}/scripts/package-ipa.sh"
"${ROOT}/scripts/package-ipa.sh" "$APP_STAGE" --name "$IPA_NAME" --out-dir "$OUT_DIR"
[[ -f "$IPA_PATH" ]] || die "package-ipa.sh finished but the IPA is missing: $IPA_PATH"

if command -v unzip >/dev/null 2>&1; then
  if unzip -p "$IPA_PATH" "Payload/${APP_BASENAME}/GameCatalog.json" > "${WORK}/ipa-catalog.json" 2>/dev/null; then
    if ! cmp -s "$CATALOG" "${WORK}/ipa-catalog.json"; then
      die "the IPA's GameCatalog.json does not match the generated catalogue"
    fi
    log "verified: the IPA carries the generated GameCatalog.json"
  else
    warn "could not read Payload/${APP_BASENAME}/GameCatalog.json from the IPA (unzip)"
  fi
else
  warn "unzip not found; skipped the catalogue-in-IPA verification"
fi

IPA_SHA="$(desktop_aot_sha256 "$IPA_PATH")"
IPA_BYTES="$(desktop_aot_file_bytes "$IPA_PATH")"
MANIFEST="${OUT_DIR}/${IPA_NAME}.pack-manifest.txt"
{
  printf 'name=%s\n' "$IPA_NAME"
  printf 'version=%s\n' "$VERSION"
  printf 'mode=%s\n' "$MODE"
  printf 'packages=%s\n' "$PACKAGE_COUNT"
  printf 'catalog=%s\n' "$CATALOG"
  printf 'catalog_sha256=%s\n' "$CATALOG_SHA"
  printf 'ipa=%s\n' "$IPA_PATH"
  printf 'ipa_bytes=%s\n' "$IPA_BYTES"
  printf 'ipa_sha256=%s\n' "$IPA_SHA"
  while IFS= read -r dir; do
    title="$(basename "$dir")"
    printf 'package_%s_dir=%s\n' "$title" "$dir"
    printf 'package_%s_sha256=%s\n' "$title" "$(desktop_aot_sha256 "${dir}/GamePack.dylib")"
    printf 'package_%s_pack_file=%s\n' "$title" "Frameworks/GamePack-${title}.dylib"
  done < "$SELECTED_FILE"
  printf 'created_utc=%s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
} > "$MANIFEST"

log "multi-game IPA ready"
printf 'CATALOG: %s\n' "$(game_catalog_summary_text)"
printf 'PACKED: %s game(s) in one shell (%s mode)\n' "$PACKAGE_COUNT" "$MODE"
printf 'IPA: %s (%s bytes)\n' "$IPA_PATH" "$IPA_BYTES"
printf 'SHA256: %s\n' "$IPA_SHA"
printf 'MANIFEST: %s\n' "$MANIFEST"
if [[ "$MODE" == "fake-shell" ]]; then
  warn "--fake-shell produced a layout preview only; it is NOT installable. Build on macOS with --base-app for a real IPA."
fi
if [[ "$ALLOW_PLACEHOLDER" -eq 1 ]]; then
  warn "placeholder packs were accepted; the IPA contains no real AOT code and must not be shipped"
fi
printf '%s\n' "$IPA_PATH"
